pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract CallCounter {
    uint256 public count;
    function countCall() external { count++; }
    function transferFrom(address, address, uint256) external returns (bool) { count++; return true; }
}

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        CallCounter cc = new CallCounter();
        address caddress = address(cc);
        address from = address(this);
        bool refSuccess = c.transfer(from, caddress, _tos, v);
        assertTrue(cc.count() >= _tos.length);
    }
}
